{
  "world_view": {
    "name": "崩坏3",
    "universe": "崩坏宇宙",
    "setting": {
      "era": "现代与未来交织",
      "dimensions": "多维宇宙",
      "world_description": "《崩坏3》所描述的是一个由神秘力量“崩坏”所侵蚀的世界。在这个世界中，人类社会面临着崩坏能的威胁，崩坏是一种超自然灾害，能够腐蚀生物和物质，带来强大的破坏。为了抵抗崩坏，人类建立了抵抗组织，例如‘天命’、‘逆熵’等，组织中诞生了许多强大的战士，称为‘女武神’。崩坏能催生出神秘生物‘崩坏兽’以及强大的个体‘律者’。律者代表着崩坏意志的代言人，但也有些律者选择抗拒崩坏的命运，帮助人类对抗灾难。",
      "factions": [
        {
          "name": "天命",
          "description": "一个历史悠久的组织，致力于消灭崩坏力量，拥有许多强大的战士和科技力量。天命由神父奥托·阿波卡利斯统领，组织的总部位于欧洲。",
          "key_characters": ["奥托·阿波卡利斯", "德丽莎·阿波卡利斯", "卡莲·卡斯兰娜"]
        },
        {
          "name": "逆熵",
          "description": "一个以科技与科学为导向的反崩坏组织，强调科技对抗崩坏，采用机械化的战斗方式。由瓦尔特·乔伊斯创立。",
          "key_characters": ["符华", "布洛妮娅·扎伊切克"]
        },
        {
          "name": "逐火之蛾",
          "description": "在第一文明纪元成立的抵抗崩坏组织，是人类历史上第一次全面对抗崩坏的尝试。逐火英桀是组织中的核心成员。",
          "key_characters": ["爱莉希雅", "凯文·卡斯兰娜"]
        }
      ],
      "power_sources": {
        "崩坏能": "一种神秘的能量，能够操纵物质，改变生命形态，极具破坏性。",
        "律者力量": "拥有强大力量的个体，代表着崩坏的意志，但也有一些律者反叛崩坏的控制，帮助人类。"
      },
      "technology_level": "人类科技已经达到与崩坏能抗衡的程度，但崩坏带来的威胁远超科技的发展，尤其是在律者的干涉下，科技与超自然力量常常交织在一起。"
    }
  }
}

{
  "character_details": {
    "name": "德丽莎·阿波卡利斯",
    "gender": "female",
    "height": "145 cm",
    "weight": "38 kg",
    "measurements": {
